const float h3 = h2 * h;
const float h6 = h3 * h3;
const float poly6 = 315.0f / (64.0f * 3.14159265f * h6);

for (size_t i = start; i < end; ++i) {
    Particle &pi = particles[i];
    glm::vec3 fPressure(0.0f);
    glm::vec3 fViscosity(0.0f);

    glm::ivec3 cell = getCell(&pi, h);
    for (int x = -1; x <= 1; ++x) {
        for (int y = -1; y <= 1; ++y) {
            for (int z = -1; z <= 1; ++z) {
                uint32_t hash = getHash(cell + glm::ivec3(x, y, z));
                uint32_t idx = particleTable[hash & (TABLE_SIZE - 1)];
                while (idx != NO_PARTICLE) {
                    const Particle &pj = particles[idx];
                    glm::vec3 rVec = pi.position - pj.position;
                    float r2 = glm::dot(rVec, rVec);
                    if (r2 < h2 && r2 > 1e-6f) {
                        float r = std::sqrt(r2);
                        glm::vec3 rNorm = rVec / r;

                        // Pressure force
                        float pTerm = (pi.pressure + pj.pressure) / (2.0f * pj.density);
                        float spiky = spikyGrad * (h - r) * (h - r);
                        fPressure += -mass * pTerm * spiky * rNorm;

                        // Viscosity force
                        float vTerm = viscosity * mass / pj.density;
                        float spikyLap = spikyLap * (h - r);
                        fViscosity += vTerm * spikyLap * (pj.velocity - pi.velocity);
                    }
                    idx = pj.next;
                }
            }
        }
    }
    pi.force = fPressure + fViscosity;
}

